-- GWE bid import (18 solicitations). Run AFTER gwe_leads_bids.sql + gwe_bids_extend.sql.
-- Idempotent: skips a bid if the same solicitation_no already exists.

insert into bids (project, service_type, gate, reason, solicitation_no, issuer, issuer_type, county, city, status, due_date, walkthrough, walkthrough_date, questions_due, portal_link, contact_name, contact_phone, contact_email, scope, steps_apply, steps_walk, intent_email)
select 'Janitorial Services in Alameda and San Francisco County', 'Janitorial', 'PASS', 'Caltrans janitorial; Alameda Co = P2 ~50mi; mandatory job-walk 08/10 not missed; 20 days to close.', '04A7443', 'State of California - Caltrans (Dist 04)', 'State', 'Alameda', 'Alameda & SF County', 'prospect', '2026-08-20'::date, 'Y - Mandatory Job-Walk 08/10/2026 (3 sessions: 8:45 / 10:30 / 12:30 PM PDT)', '2026-08-10'::date, '2026-08-11'::date, 'https://caleprocure.ca.gov/event/2660/04A7443', 'Angel Cervantes Jr.', '916-201-3927', 'Angel.Cervantes.Jr@dot.ca.gov', 'Caltrans Dist 04 janitorial: all labor, tools, materials, supplies, equipment at Alameda (1993 Marina Blvd + others) & SF sites. Term 10/01/2026-09/30/2027.', '1) Register/log in at caleprocure.ca.gov. 2) Open Event 04A7443. 3) Download IFB + attachments. 4) Attend a mandatory 08/10 job-walk. 5) Submit questions by 08/11 5:00 PM. 6) Submit bid electronically before 08/20 2:00 PM PDT.', 'Attend ONE mandatory 08/10 session (8:45/10:30/12:30). Email Angel.Cervantes.Jr@dot.ca.gov or call 916-201-3927 to confirm session + pre-registration. Bring ID, sign attendance sheet (required to bid).', 'Subject: GWE - Intent to Bid, 04A7443 Janitorial Services (Caltrans Dist 04)

Hi Angel,

Great Way Environmental is a licensed commercial janitorial contractor serving Alameda County. We''re preparing a response to 04A7443 - Janitorial Services in Alameda and San Francisco County (closing 08/20).

Could you confirm which of the 08/10 mandatory job-walk sessions (8:45 / 10:30 / 12:30) we should attend and whether pre-registration is required? Want to make sure our submission is complete.

Appreciate it,
Fernando Gonzalez
Great Way Environmental'
where not exists (select 1 from bids where solicitation_no = '04A7443');
